import sys
import os
import tempfile
import shutil
from hae.evaluation.harness import ExecutionHarness, SKIPPED, PASSED, GateResult

def test_probe():
    tmpdir = tempfile.mkdtemp()
    try:
        content = 'import nonexistent_pkg_1234567890',
        bundle = {
            'test_missing.py': content,
            'pyproject.toml': '[project]'
        }

        harness = ExecutionHarness()
        report = harness.verify_bundle(bundle, source='bundle')

        # Check the raw gate result vs the report status
        tests_gate = report.gate('tests')
        if tests_gate:
            print(f'Raw Gate Status: {tests_gate.status}')
            print(f'Report Gate Status: {report.gate_status.get('tests')}')

            if tests_gate.status == 'skipped' and report.gate_status.get('tests') == 'passed':
                print('VERDICT: AGGREGATION_BUG')
            elif tests_gate.status == 'skipped' and report.gate_status.get('tests') == 'skipped':
                print('VERDICT: CORRECT_SKIPPED')
            elif tests_gate.status == 'passed':
                print('VERDICT: GATE_RETURNED_PASSED')
            else:
                print('VERDICT: OTHER')
        else:
            print('VERDICT: NO_GATE')
    finally:
        shutil.rmtree(tmpdir)

test_probe()

